/* -------------------------------- APP -------------------------------- */

/* ------------------------- AMBIENT SIDE GALLERY ------------------------- */
// A subtle, non-intrusive fleet photo that rides along the side of the
// screen as the visitor moves through the site. It never covers the full
// background — just a soft accent strip — and swaps image per page so it
// stays fresh without ever fighting with the readable content.
function SideAmbientGallery({ page }) {
  const pageIndex = { home: 0, details: 1, booking: 2, success: 3 }[page] ?? 4;
  const img = BG_IMAGES[pageIndex % BG_IMAGES.length];
  return (
    <div className="side-ambient" aria-hidden="true">
      <img src={img} alt="" />
    </div>
  );
}

export default function App() {
  return (
    <LangProvider>
      <AppInner />
    </LangProvider>
  );
}

function AppInner() {
  const [page, setPage] = useState("home");
  const [activeCarId, setActiveCarId] = useState(null);
  const [cars, setCars] = useState([]);
  const [loadingCars, setLoadingCars] = useState(true);
  const [loadError, setLoadError] = useState("");
  const [socialLinks, setSocialLinks] = useState({ facebook_url: "", instagram_url: "" });
  const homeRef = useReveal([page, loadingCars]);

  useEffect(() => {
    let cancelled = false;
    const load = async (silent) => {
      try {
        const rows = await getCars();
        if (!cancelled) setCars(rows);
      } catch (err) {
        if (!cancelled && !silent) setLoadError("تعذر تحميل السيارات حاليًا حاول تحديث الصفحة.");
      } finally {
        if (!cancelled && !silent) setLoadingCars(false);
      }
    };
    load(false);
    // Quiet background refresh so an availability change made from the
    // admin dashboard shows up here automatically while browsing.
    const poll = setInterval(() => load(true), 15000);
    return () => {
      cancelled = true;
      clearInterval(poll);
    };
  }, []);

  useEffect(() => {
    let cancelled = false;
    const loadSocial = async () => {
      const links = await getSocialLinks();
      if (!cancelled) setSocialLinks(links);
    };
    loadSocial();
    // Facebook/Instagram buttons activate on their own the moment the admin
    // saves a link in the dashboard — no page reload needed here.
    const poll = setInterval(loadSocial, 15000);
    return () => {
      cancelled = true;
      clearInterval(poll);
    };
  }, []);

  const openDetails = (id) => {
    setActiveCarId(id);
    setPage("details");
    window.scrollTo({ top: 0, behavior: "auto" });
  };
  const openBooking = (id) => {
    setActiveCarId(id || null);
    setPage("booking");
    window.scrollTo({ top: 0, behavior: "auto" });
  };
  const goHome = () => {
    setPage("home");
    setActiveCarId(null);
    window.scrollTo({ top: 0, behavior: "auto" });
  };
  const goBack = () => {
    if (page === "booking") setPage(activeCarId ? "details" : "home");
    else setPage("home");
    window.scrollTo({ top: 0, behavior: "auto" });
  };

  const activeCar = cars.find((c) => c.id === activeCarId) || null;

  return (
    <div className="app-root" dir="rtl">
      <GlobalStyles />
      <SiteAmbientLights />
      <SideAmbientGallery page={page} />
      <Header page={page} onBack={goBack} />

      {page === "home" && (
        <main ref={homeRef}>
          <Hero carCount={cars.length} />
          <HowItWorks />
          {loadingCars ? (
            <div className="fleet-loading">
              <Loader2 className="spin-icon" size={26} />
              <span>جارٍ تحميل الأسطول...</span>
            </div>
          ) : loadError ? (
            <p style={{ textAlign: "center", padding: "40px 0", color: "#E5544D" }}>
              {loadError}
            </p>
          ) : (
            <CarsSection cars={cars} onOpen={openDetails} />
          )}
          <FleetShowcase />
          <VisitUs />
          <Footer />
        </main>
      )}

      {page === "details" && activeCar && (
        <main>
          <CarDetails car={activeCar} onBook={openBooking} />
        </main>
      )}

      {page === "booking" && (
        <main>
          <BookingPage cars={cars} preselectedId={activeCarId} onDone={goHome} />
        </main>
      )}

      <WhatsappFloat
        visible={page === "home"}
        facebookUrl={socialLinks.facebook_url}
        instagramUrl={socialLinks.instagram_url}
      />
    </div>
  );
}

/* ------------------------------- STYLES ------------------------------- */

function GlobalStyles() {
  return (
    <style>{`
      @import url('https://fonts.googleapis.com/css2?family=Tajawal:wght@300;400;500;700;800;900&family=Poppins:wght@500;600;700&family=Cormorant+Garamond:ital,wght@1,500;1,600;1,700&display=swap');

      :root{
        --bg:#0B0B0B;
        --card:#161616;
        --card-border: rgba(154,163,172,0.14);
        --primary:#9AA3AC;
        --primary-light:#D6DBE0;
        --text:#FFFFFF;
        --text-sec:#9A9A9A;
        --green:#33C36F;
        --red:#E5544D;
        /* Extra brand palette woven through the UI */
        --gold:#B8912F;
        --gold-light:#E8C874;
        --silver:#9AA1A8;
        --silver-light:#D7DBDF;
        --cool-green:#1FCFA0;
        --cool-green-light:#5CE8C4;
        --blue:#2E6FF2;
        --blue-light:#6E9CFF;
        --accent-black:#0A0A0A;
        --radius:16px;
      }

      /* Carbon-fiber weave, used across roughly a third of the surfaces
         (header, footer, sticky bar, nav pills, spec icons, buttons) to
         pair with the new silver palette. */
      .carbon-fiber{
        background-color:#161616;
        background-image:
          repeating-linear-gradient(45deg, rgba(255,255,255,0.05) 0, rgba(255,255,255,0.05) 1px, transparent 1px, transparent 5px),
          repeating-linear-gradient(-45deg, rgba(0,0,0,0.55) 0, rgba(0,0,0,0.55) 1px, transparent 1px, transparent 5px),
          linear-gradient(160deg, rgba(255,255,255,0.06), transparent 40%);
        background-size:7px 7px, 7px 7px, 100% 100%;
      }

      *{box-sizing:border-box; -webkit-tap-highlight-color: transparent;}
      /* Keep the page's own scrollbar pinned to the right even though the
         content is RTL — only .app-root flips to RTL for the Arabic layout. */
      html, body{ direction:ltr; scroll-behavior:smooth; }

      /* ---------- Custom scrollbar: long, carbon-fiber weave, fades in on load, right side ---------- */
      @keyframes scrollbarFadeIn{
        from{ opacity:0; }
        to{ opacity:1; }
      }
      html{
        scrollbar-width:thin;
        scrollbar-color:#2b2b2f transparent;
      }
      ::-webkit-scrollbar{ width:9px; height:9px; }
      ::-webkit-scrollbar-track{
        background:rgba(10,10,12,0.25);
      }
      ::-webkit-scrollbar-thumb{
        /* Carbon-fiber weave: a diagonal crosshatch over a graphite gradient */
        background-image:
          repeating-linear-gradient(45deg, rgba(0,0,0,0.55) 0 2px, rgba(60,60,66,0.35) 2px 4px),
          repeating-linear-gradient(-45deg, rgba(0,0,0,0.5) 0 2px, rgba(50,50,56,0.3) 2px 4px),
          linear-gradient(180deg, #38383d 0%, #17171a 20%, #0c0c0e 50%, #17171a 80%, #38383d 100%);
        background-blend-mode:overlay, overlay, normal;
        border-radius:999px;
        border:1px solid rgba(120,120,130,0.25);
        min-height:340px;
        opacity:0;
        animation:scrollbarFadeIn 1.1s ease forwards .15s;
      }
      ::-webkit-scrollbar-thumb:hover{
        background-image:
          repeating-linear-gradient(45deg, rgba(0,0,0,0.55) 0 2px, rgba(80,80,88,0.4) 2px 4px),
          repeating-linear-gradient(-45deg, rgba(0,0,0,0.5) 0 2px, rgba(70,70,78,0.35) 2px 4px),
          linear-gradient(180deg, #4a4a50 0%, #222226 20%, #131315 50%, #222226 80%, #4a4a50 100%);
      }
      body,.app-root{
        background:var(--bg);
        color:var(--text);
        font-family:'Tajawal',sans-serif;
        margin:0;
        min-height:100vh;
        overflow-x:hidden;
      }
      .app-root{ position:relative; isolation:isolate; }
      .app-root::after{
        content:"";
        position:fixed; inset:0;
        background:
          linear-gradient(180deg, rgba(11,11,11,0.95), rgba(11,11,11,0.9) 35%, rgba(11,11,11,0.97)),
          linear-gradient(125deg, rgba(154,163,172,0.14), transparent 55%),
          url('https://images.unsplash.com/photo-1503376780353-7e6692767b70?q=80&w=2000&auto=format&fit=crop') center/cover no-repeat;
        opacity:0.55;
        pointer-events:none;
        z-index:-2;
      }
      /* ---------- Site-wide ambient background: the real reference photo
         (Audi / Mercedes / BMW marks with the glowing light-ray fan) used
         directly as the background image. Fixed behind the ENTIRE site
         (every page/section), not just the hero, so it never disappears
         while browsing. Same automation as the old background it
         replaces: it ignites once with a gradual dim-to-bright rise,
         then keeps breathing forever after (glow gradually rises then
         falls) via an opacity/brightness pulse on the photo itself. ---------- */
      .site-ambient-lights{
        position:fixed; inset:0; z-index:-1;
        pointer-events:none; user-select:none; overflow:hidden;

        --amb-rise:1.8s;
        --amb-start:0.2s;
        --amb-ambient:0.85;
      }
      .amb-photo{
        position:absolute; inset:0;
        background-size:cover;
        background-position:center top;
        background-repeat:no-repeat;
        opacity:0;
        animation:ambPhotoIn var(--amb-rise) cubic-bezier(.22,.61,.36,1) var(--amb-start) forwards;
      }
      @keyframes ambPhotoIn{
        0%{ opacity:0; filter:brightness(0.7); }
        100%{ opacity:var(--amb-ambient); filter:brightness(1); }
      }
      @media (prefers-reduced-motion: reduce){
        .amb-photo{ animation:none; opacity:var(--amb-ambient); }
      }

      /* ---------- Choreographed ignition, layered ON TOP of .amb-photo
         above (which is untouched): the same photo re-masked into right
         light-strands, left light-strands, and the three brand marks so
         each piece can ignite on its own timeline, then keep breathing
         forever. Nothing here changes the base background/design. ---- */
      .amb-strip, .amb-logo{
        position:absolute; inset:0;
        background-size:cover;
        background-position:center top;
        background-repeat:no-repeat;
        opacity:0;
        filter:brightness(0.3);
      }
      .amb-strip{
        animation-name:ambStripIgnite;
        animation-duration:0.95s;
        animation-timing-function:cubic-bezier(.22,.61,.36,1);
        animation-fill-mode:forwards;
        animation-iteration-count:1;
        animation-delay:var(--strip-delay, 0s);
      }
      @keyframes ambStripIgnite{
        0%{ opacity:0; filter:brightness(0.22); }
        55%{ opacity:0.6; filter:brightness(0.65); }
        100%{ opacity:1; filter:brightness(1); }
      }
      .amb-logo{
        transform-origin:center;
        animation-name:ambLogoRise;
        animation-duration:1.15s;
        animation-timing-function:cubic-bezier(.22,.61,.36,1);
        animation-fill-mode:forwards;
        animation-iteration-count:1;
        animation-delay:var(--logo-delay, 0s);
      }
      @keyframes ambLogoRise{
        0%{ opacity:0; filter:brightness(0.28) drop-shadow(0 0 0 rgba(255,255,255,0)); transform:scale(0.97); }
        60%{ opacity:0.68; filter:brightness(0.72) drop-shadow(0 0 4px rgba(255,255,255,0.15)); transform:scale(0.995); }
        100%{ opacity:1; filter:brightness(1) drop-shadow(0 0 10px rgba(255,255,255,0.3)); transform:scale(1); }
      }
      @media (prefers-reduced-motion: reduce){
        .amb-strip, .amb-logo, .amb-logo-audi, .amb-logo-mercedes, .amb-logo-bmw{
          animation:none !important; opacity:1; filter:brightness(1) !important; transform:none !important;
        }
      }

      h1,h2,h3{ font-family:'Tajawal',sans-serif; margin:0; font-weight:900; }
      p{ margin:0; color:var(--text-sec); line-height:1.8; font-size:0.95rem; }
      a{ text-decoration:none; color:inherit; }
      button{ font-family:'Tajawal',sans-serif; cursor:pointer; border:none; background:none; color:inherit; }
      input,select{ font-family:'Tajawal',sans-serif; }

      .desktop-only{ display:none; }
      @media (min-width:900px){
        .desktop-only{ display:flex; }
        .mobile-only{ display:none; }
      }
      /* Phone numbers only appear once there's real room for them, so the
         nav + language switch never get pushed off-screen on mid-size
         (tablet / small laptop) widths. */
      .wide-only{ display:none; }
      @media (min-width:1180px){
        .wide-only{ display:flex; }
      }

      /* ---------- Reveal ---------- */
      .reveal{ opacity:0; transform:translateY(28px); transition:opacity .7s cubic-bezier(.22,.61,.36,1), transform .7s cubic-bezier(.22,.61,.36,1); }
      .reveal.show{ opacity:1; transform:translateY(0); }

      /* ---------- Letters fading in one by one on entry, fast & smooth ---------- */
      @keyframes typeFadeChar{
        from{ opacity:0; transform:translateY(6px); filter:blur(2px); }
        to{ opacity:1; transform:translateY(0); filter:blur(0); }
      }
      .type-fade{ display:inline-block; }
      .type-fade-char{
        display:inline-block; opacity:0;
        animation:typeFadeChar .38s ease forwards;
      }

      /* ---------- Glowing underline that fades in gradually beneath key
         sentences, each with its own accent color — same tapered-line shape
         and same one-time entrance fade as the header brand-glow-line ---------- */
      @keyframes glowUnderlineIn{
        from{ opacity:0; transform:scaleX(0); }
        to{ opacity:1; transform:scaleX(1); }
      }
      .glow-underline{ position:relative; display:inline-block; padding-bottom:6px; }
      .glow-underline::after{
        content:""; position:absolute; left:0; right:0; bottom:0; height:1.5px;
        border-radius:2px; transform-origin:center;
        opacity:0; transform:scaleX(0.35);
        animation:brandGlowFadeIn 1.6s cubic-bezier(.22,.61,.36,1) .35s forwards;
      }
      .glow-underline.glow-gold::after{
        background:linear-gradient(90deg, transparent, rgba(232,200,116,0.18) 15%, var(--gold-light) 50%, rgba(232,200,116,0.18) 85%, transparent);
        box-shadow:0 0 6px rgba(184,145,47,0.4);
      }
      .glow-underline.glow-red::after{
        background:linear-gradient(90deg, transparent, rgba(200,30,30,0.18) 15%, #c81e1e 50%, rgba(200,30,30,0.18) 85%, transparent);
        box-shadow:0 0 6px rgba(200,30,30,0.4);
      }
      .glow-underline.glow-silver::after{
        background:linear-gradient(90deg, transparent, rgba(215,219,223,0.18) 15%, var(--silver) 50%, rgba(215,219,223,0.18) 85%, transparent);
        box-shadow:0 0 6px rgba(154,163,172,0.4);
      }
      @media (prefers-reduced-motion: reduce){
        .glow-underline::after{ opacity:1; transform:scaleX(1); animation:none; }
      }

      /* ---------- Buttons ---------- */
      .btn{
        display:inline-flex; align-items:center; justify-content:center;
        padding:14px 28px; border-radius:999px; font-weight:700; font-size:0.95rem;
        transition:transform .22s cubic-bezier(.34,1.56,.64,1), box-shadow .22s ease, background .22s ease, border-color .22s ease;
        touch-action:manipulation; white-space:nowrap; position:relative; overflow:hidden;
      }
      .btn:active{ transform:scale(.94); }
      .btn-primary{ background:linear-gradient(155deg,var(--blue-light),var(--blue)); color:#fff; box-shadow:0 8px 22px rgba(46,111,242,0.35); font-weight:700; }
      .btn-primary::after{
        content:""; position:absolute; inset:0; border-radius:inherit;
        background:linear-gradient(120deg, transparent 30%, rgba(255,255,255,0.35) 50%, transparent 70%);
        background-size:220% 100%; background-position:120% 0; opacity:0; transition:opacity .3s ease;
        pointer-events:none;
      }
      .btn-primary:active{ box-shadow:0 2px 10px rgba(154,163,172,0.35); }
      .btn-primary:disabled{ background:#3a3a3a; color:#8a8a8a; box-shadow:none; cursor:not-allowed; }
      @media (min-width:900px){
        .btn-primary:hover{ transform:translateY(-2px); box-shadow:0 12px 30px rgba(154,163,172,0.45); }
        .btn-primary:hover::after{ opacity:1; background-position:-20% 0; transition:background-position .6s ease, opacity .3s ease; }
        .btn-ghost:hover{ border-color:rgba(255,255,255,0.5); background:rgba(255,255,255,0.05); }
      }
      /* Hero "احجز الآن" button: same shape as the other buttons, blue
         instead of gold, with a gentle shake that keeps looping the whole
         time the site is open (not just on hover), so it keeps drawing
         the eye. Reduced-motion users get the color without the motion. */
      .btn-hero-shake{
        background:linear-gradient(155deg,var(--blue-light),var(--blue)); color:#fff;
        box-shadow:0 8px 22px rgba(46,111,242,0.4); font-weight:700;
        animation:heroBtnShake 3.2s ease-in-out infinite;
      }
      .btn-hero-shake:active{ box-shadow:0 2px 10px rgba(46,111,242,0.35); }
      @media (min-width:900px){
        .btn-hero-shake:hover{ transform:translateY(-2px); box-shadow:0 12px 30px rgba(46,111,242,0.5); }
      }
      @keyframes heroBtnShake{
        0%, 84%, 100%{ transform:translateX(0) rotate(0); }
        86%{ transform:translateX(-3px) rotate(-2deg); }
        88%{ transform:translateX(3px) rotate(2deg); }
        90%{ transform:translateX(-3px) rotate(-2deg); }
        92%{ transform:translateX(3px) rotate(2deg); }
        94%{ transform:translateX(-2px) rotate(-1deg); }
        96%{ transform:translateX(2px) rotate(1deg); }
      }
      @media (prefers-reduced-motion: reduce){
        .btn-hero-shake{ animation:none; }
      }
      .btn-ghost{ background:transparent; color:var(--text); border:1px solid rgba(255,255,255,0.25); }
      .btn-ghost:active{ background:rgba(255,255,255,0.06); }
      .btn-block{ width:100%; }

      /* ---------- Ripple click feedback ---------- */
      .icon-btn, .header-call, .footer-phone, .wa-float, .social-float, .mobile-menu-call{ position:relative; overflow:hidden; }
      .ripple-effect{
        position:absolute; border-radius:50%; transform:scale(0);
        background:rgba(255,255,255,0.55); pointer-events:none;
        animation:rippleAnim .65s cubic-bezier(.22,.61,.36,1) forwards;
      }
      @keyframes rippleAnim{ to{ transform:scale(2.6); opacity:0; } }

      /* ---------- Header ---------- */
      .site-header{
        position:sticky; top:0; z-index:50;
        background:rgba(11,11,11,0.75);
        backdrop-filter:blur(14px);
        border-bottom:1px solid rgba(255,255,255,0.06);
      }
      .site-header-row{
        display:flex; align-items:center; justify-content:space-between; gap:10px;
        padding:14px 18px; max-width:1200px; margin:0 auto;
      }
      .brand{ display:flex; align-items:center; gap:8px; flex-shrink:0; }
      .brand-logo{
        width:42px; height:42px; border-radius:10px; object-fit:contain;
        background:#fff; padding:3px; flex-shrink:0;
      }
      .brand-text{ display:flex; flex-direction:column; line-height:1.2; max-width:150px; }
      .brand-name{
        font-family:'Cormorant Garamond','Poppins',sans-serif; letter-spacing:0.3px;
        font-size:0.78rem; white-space:normal; word-break:break-word;
        background:linear-gradient(90deg, var(--silver), var(--primary-light) 55%, var(--silver));
        -webkit-background-clip:text; background-clip:text; color:transparent;
      }
      .brand-sub{ font-size:0.56rem; color:var(--gold-light); letter-spacing:0.2px; white-space:nowrap; }
      /* A full-width gold line that glows in once when the page loads, then
         stays a soft static shimmer — no continuous motion. */
      .brand-glow-line{
        display:block; width:100%; min-width:64px; height:1.5px; margin-top:6px; border-radius:2px;
        background:linear-gradient(90deg, transparent, rgba(232,200,116,0.18) 15%, var(--gold-light) 50%, rgba(232,200,116,0.18) 85%, transparent);
        box-shadow:0 0 6px rgba(184,145,47,0.4);
        opacity:0; transform:scaleX(0.35);
        transform-origin:center;
        animation:brandGlowFadeIn 1.6s cubic-bezier(.22,.61,.36,1) .35s forwards;
      }
      @keyframes brandGlowFadeIn{
        to{ opacity:1; transform:scaleX(1); }
      }
      @media (prefers-reduced-motion: reduce){
        .brand-glow-line{ opacity:1; transform:scaleX(1); animation:none; }
      }
      /* Footer version of the same glowing line: stays hidden (no
         auto-play) until the footer scrolls into view and picks up the
         shared .reveal "show" class — then it fades/glows in exactly like
         the other lines on the site, just triggered by scroll instead of
         page load. */
      .brand-glow-line-scroll{ animation:none; }
      .footer.show .brand-glow-line-scroll{
        animation:brandGlowFadeIn 1.6s cubic-bezier(.22,.61,.36,1) .35s forwards;
      }
      @media (prefers-reduced-motion: reduce){
        .footer.show .brand-glow-line-scroll{ opacity:1; transform:scaleX(1); animation:none; }
      }
      /* ---------- Language switch ---------- */
      .lang-switch{
        display:flex; align-items:center; gap:3px;
        padding:3px; border-radius:999px;
        border:1px solid rgba(154,163,172,0.22);
        background:rgba(255,255,255,0.02);
      }
      .lang-switch-btn{
        border:none; background:transparent; color:var(--text-sec);
        font-family:'Poppins',sans-serif; font-size:0.62rem; font-weight:600;
        letter-spacing:0.3px; padding:4px 8px; border-radius:999px; cursor:pointer;
        transition:color .2s ease, background .2s ease;
      }
      .lang-switch-btn.active{
        color:var(--accent-black);
        background:linear-gradient(155deg,var(--gold-light),var(--gold));
      }
      .lang-switch.mini{ padding:2px; gap:1px; }
      .lang-switch.mini .lang-switch-btn{ font-size:0.52rem; padding:3px 6px; }
      .nav-links{
        display:flex; gap:6px; align-items:center;
        padding:6px; border:1px solid rgba(154,163,172,0.25); border-radius:999px;
        background:rgba(255,255,255,0.02);
      }
      .nav-pill{
        position:relative; overflow:hidden;
        display:flex; align-items:center; justify-content:center;
        padding:9px 16px; border-radius:999px;
        font-size:0.85rem; font-weight:600; color:var(--text-sec);
        border:1px solid rgba(154,163,172,0.22);
        background:linear-gradient(135deg, rgba(154,163,172,0.16), rgba(20,20,20,0.92));
        transition:color .2s ease, border-color .2s ease, transform .18s cubic-bezier(.34,1.56,.64,1), box-shadow .2s ease;
        opacity:0; transform:translateY(-8px);
        animation:navPillIn .5s cubic-bezier(.22,.61,.36,1) forwards;
      }
      .nav-pill:nth-child(1){ animation-delay:.15s; background:linear-gradient(135deg, rgba(154,163,172,0.22), rgba(20,20,20,0.92)); border-color:rgba(154,163,172,0.3); }
      .nav-pill:nth-child(2){ animation-delay:.28s; background:linear-gradient(135deg, rgba(154,163,172,0.22), rgba(20,20,20,0.92)); border-color:rgba(154,163,172,0.3); }
      .nav-pill:nth-child(3){ animation-delay:.41s; background:linear-gradient(135deg, rgba(154,163,172,0.22), rgba(20,20,20,0.92)); border-color:rgba(154,163,172,0.3); }
      .nav-pill:nth-child(4){ animation-delay:.54s; background:linear-gradient(135deg, rgba(31,207,160,0.2), rgba(20,20,20,0.92)); border-color:rgba(31,207,160,0.3); }
      @keyframes navPillIn{ to{ opacity:1; transform:translateY(0); } }
      .nav-pill:hover{ color:var(--text); border-color:rgba(154,163,172,0.55); transform:translateY(-2px); box-shadow:0 8px 18px rgba(0,0,0,0.35); }
      .nav-pill:active{ transform:translateY(0) scale(.95); }
      @media (prefers-reduced-motion: reduce){
        .nav-pill{ opacity:1; transform:none; animation:none; }
      }
      .header-calls{ display:flex; align-items:center; gap:8px; }
      .header-call{ display:flex; align-items:center; gap:6px; border:1px solid var(--silver); padding:9px 16px; border-radius:999px; font-size:0.85rem; color:var(--silver-light); }
      .icon-btn{ width:40px; height:40px; display:flex; align-items:center; justify-content:center; border-radius:10px; transition:transform .18s cubic-bezier(.34,1.56,.64,1), background .18s ease; }
      .icon-btn:hover{ background:rgba(255,255,255,0.06); }
      .icon-btn:active{ transform:scale(.88); }
      .icon-btn:active{ background:rgba(255,255,255,0.08); }
      .icon-btn.placeholder{ visibility:hidden; }
      .mobile-menu{ display:flex; flex-direction:column; padding:12px 18px 18px; gap:8px; border-top:1px solid rgba(154,163,172,0.2); }
      .mobile-menu .nav-pill{
        width:100%; padding:14px 16px; border-radius:14px; justify-content:flex-start; font-size:1rem; color:var(--text);
        opacity:0; transform:translateX(14px);
        animation:navPillInMobile .4s cubic-bezier(.22,.61,.36,1) forwards;
      }
      .mobile-menu .nav-pill:nth-child(1){ animation-delay:.06s; }
      .mobile-menu .nav-pill:nth-child(2){ animation-delay:.14s; }
      .mobile-menu .nav-pill:nth-child(3){ animation-delay:.22s; }
      .mobile-menu .nav-pill:nth-child(4){ animation-delay:.30s; }
      @keyframes navPillInMobile{ to{ opacity:1; transform:translateX(0); } }
      .mobile-menu-call{ display:flex; align-items:center; gap:8px; margin-top:10px; color:var(--primary-light); font-weight:700; }

      .app-header{
        position:sticky; top:0; z-index:50; display:flex; align-items:center; justify-content:space-between;
        padding:14px 14px; background:rgba(11,11,11,0.9); backdrop-filter:blur(14px); border-bottom:1px solid rgba(255,255,255,0.06);
      }
      .app-header-title{ font-weight:700; font-size:1rem; }

      /* ---------- Hero ---------- */
      .hero{ position:relative; min-height:92vh; display:flex; align-items:flex-end; overflow:hidden; perspective:1000px; }
      .hero-media{ position:absolute; inset:-10% 0 0 0; height:120%; transition:transform .35s cubic-bezier(.22,.61,.36,1); transform-style:preserve-3d; will-change:transform; }
      .hero-media img{ width:100%; height:100%; object-fit:cover; }
      .hero-overlay{
        position:absolute; inset:0;
        background:
          linear-gradient(0deg, rgba(11,11,11,1) 8%, rgba(11,11,11,0.7) 45%, rgba(11,11,11,0.3) 75%),
          linear-gradient(90deg, rgba(11,11,11,0.6), rgba(11,11,11,0.1)),
          radial-gradient(ellipse at 30% 100%, rgba(154,163,172,0.25), transparent 60%);
      }
      .hero-content{ position:relative; z-index:2; padding:0 20px 64px; max-width:640px; }
      .eyebrow{ display:inline-block; font-size:0.78rem; letter-spacing:1px; color:var(--primary-light); font-weight:700; margin-bottom:14px; }
      .hero h1{ font-size:clamp(2.3rem,9vw,3.6rem); line-height:1.05; margin-bottom:18px; }
      .hero h1 .dot{ color:var(--primary); }
      .hero p{ font-size:1rem; max-width:480px; margin-bottom:26px; }
      .hero-actions{ display:flex; gap:12px; flex-wrap:wrap; }
      .hero-stats{ display:flex; gap:28px; margin-top:34px; flex-wrap:wrap; }
      .hero-stat{ display:flex; flex-direction:column; }
      .hero-stat strong{ font-family:'Poppins',sans-serif; font-size:1.5rem; font-weight:700; color:var(--primary-light); }
      .hero-stat span{ font-size:0.78rem; color:var(--text-sec); margin-top:2px; }

      /* ---------- How it works ---------- */
      .how-section{ max-width:1200px; margin:60px auto 0; padding:0 18px; text-align:center; }
      .how-section h2{ font-size:1.6rem; margin-bottom:32px; }
      .how-grid{ display:grid; grid-template-columns:1fr; gap:16px; }
      @media (min-width:760px){ .how-grid{ grid-template-columns:repeat(3,1fr); } }
      .how-card{ position:relative; background:var(--card); border:1px solid var(--card-border); border-radius:18px; padding:28px 20px; text-align:right; }

      /* ---------- LED frame: a thin light chasing around the card edge ---------- */
      @keyframes ledChase{ to{ background-position:300% 0; } }
      .led-frame{
        border:1px solid transparent !important;
        background-image:
          linear-gradient(var(--card), var(--card)),
          linear-gradient(90deg, transparent, var(--gold-light), #fff, var(--gold-light), transparent, transparent, transparent, transparent);
        background-origin:border-box;
        background-clip:padding-box, border-box;
        background-size:100% 100%, 300% 100%;
        background-repeat:no-repeat, repeat-x;
        animation:ledChase 4.5s linear infinite;
        box-shadow:0 0 10px rgba(232,200,116,0.18);
      }
      .how-num{ position:absolute; top:16px; left:20px; font-family:'Poppins',sans-serif; font-weight:700; font-size:1.6rem; color:rgba(255,255,255,0.08); }
      .how-card h3{ margin:14px 0 6px; font-size:1.05rem; }
      .how-card p{ color:var(--text-sec); font-size:0.86rem; }

      .ignition-line{ position:relative; width:120px; height:14px; margin-bottom:22px; display:flex; align-items:center; }
      .ignition-fill{ position:absolute; right:0; top:50%; transform:translateY(-50%); height:2px; width:0; background:linear-gradient(90deg,transparent,var(--primary)); animation:ignite 1.4s .9s cubic-bezier(.22,.61,.36,1) forwards; }
      .ignition-dot{ position:absolute; right:0; top:50%; width:8px; height:8px; border-radius:50%; background:var(--primary); transform:translateY(-50%); box-shadow:0 0 0 0 rgba(154,163,172,0.6); animation:pulseDot 2s 2.2s infinite; }
      @keyframes ignite{ from{ width:0; } to{ width:120px; } }
      @keyframes pulseDot{ 0%{ box-shadow:0 0 0 0 rgba(154,163,172,0.55);} 70%{ box-shadow:0 0 0 10px rgba(154,163,172,0);} 100%{ box-shadow:0 0 0 0 rgba(154,163,172,0);} }

      .hero-in{ opacity:0; transform:translateY(18px); animation:heroIn .8s cubic-bezier(.22,.61,.36,1) forwards; }
      .hero-in-1{ animation-delay:.15s; }
      .hero-in-2{ animation-delay:.3s; }
      .hero-in-3{ animation-delay:.5s; }
      .hero-in-4{ animation-delay:.65s; }
      .hero-in-5{ animation-delay:.8s; }
      @keyframes heroIn{ to{ opacity:1; transform:translateY(0); } }

      /* ---------- Hero emblem: BMW headlights only (no body/grille/bumper),
         igniting once on page load — starting dim and rising smoothly to
         their normal brightness, then staying lit permanently. Runs once,
         never re-triggers or fades back out. ---------- */
      .hero-emblem{ display:flex; flex-direction:column; align-items:center; margin-bottom:26px; }
      .hero-emblem-car{
        width:min(80vw, 460px); height:auto; display:block;
        opacity:0;
        animation:headlightIgnite 3.2s cubic-bezier(.45,0,.2,1) .35s 1 forwards;
      }
      @keyframes headlightIgnite{
        0%{   opacity:0;    filter:brightness(0.25) drop-shadow(0 0 0 rgba(255,255,255,0)); }
        40%{  opacity:0.55; filter:brightness(0.55)  drop-shadow(0 0 6px rgba(255,255,255,0.2)); }
        100%{ opacity:1;    filter:brightness(1)     drop-shadow(0 0 16px rgba(255,255,255,0.5)); }
      }
      .hero-emblem-flourish{
        width:min(60vw, 280px); height:auto; display:block; margin-top:6px;
        opacity:0; animation:glowUnderlineIn 1.2s cubic-bezier(.22,.61,.36,1) 1.1s forwards;
      }
      /* Now sits at the top of the hero (where the eyebrow text used to be):
         same glow-fade-in look and timing style as before, just earlier in
         the sequence (first thing to appear) and with spacing below it
         instead of above.
         - margin:0 auto forces true horizontal centering (it was drifting
           to one side because the parent isn't a centered flex context).
         - bottom margin increased to give breathing room before the headlights.
         - a second, looping "shimmer" animation is chained after the initial
           fade/scale-in so the ornament stays subtly alive instead of static. */
      .hero-emblem-flourish-top{
        margin:0 auto 26px;
        opacity:0; transform:scaleX(0.35); transform-origin:center;
        animation:
          glowUnderlineIn 1.2s cubic-bezier(.22,.61,.36,1) .15s forwards,
          ornamentShimmer 3.6s ease-in-out 1.4s infinite;
      }
      @keyframes ornamentShimmer{
        0%, 100%{ filter:brightness(1) drop-shadow(0 0 0 rgba(232,200,116,0)); }
        50%{ filter:brightness(1.35) drop-shadow(0 0 8px rgba(232,200,116,0.55)); }
      }
      @media (prefers-reduced-motion: reduce){
        .hero-emblem-flourish-top{ opacity:1; transform:scaleX(1); animation:none; }
      }
      @media (max-width:520px){
        .hero-emblem-car{ width:min(88vw, 340px); }
        .hero-emblem-flourish{ width:min(70vw, 220px); }
      }

      .hero-scroll-hint{ position:absolute; bottom:18px; left:50%; transform:translateX(-50%); width:22px; height:36px; border:2px solid rgba(255,255,255,0.35); border-radius:14px; z-index:2; }
      .hero-scroll-hint span{ position:absolute; top:6px; left:50%; transform:translateX(-50%); width:4px; height:8px; border-radius:2px; background:var(--primary); animation:scrollHint 1.6s infinite; }
      @keyframes scrollHint{ 0%{ opacity:1; top:6px;} 70%{ opacity:0; top:18px;} 100%{ opacity:0; top:6px;} }

      /* The cinematic hero-only intro (black curtain, per-logo spotlight,
         infinite 3D rotation) has been removed. The lights + brand marks
         now live in the site-wide .site-ambient-lights background defined
         above, which stays visible on every page instead of only the hero. */

      /* ---------- Sections ---------- */
      .section{ max-width:1200px; margin:0 auto; padding:88px 20px 48px; position:relative; }
      .section::before{
        content:""; position:absolute; top:0; left:50%; transform:translateX(-50%);
        width:120px; height:2px; background:linear-gradient(90deg,transparent,var(--primary),transparent);
        opacity:0.6;
      }
      @media (min-width:900px){ .section{ padding:110px 32px 60px; } }
      .section-head{ text-align:center; max-width:520px; margin:0 auto 28px; }
      .section-head h2{ font-size:clamp(1.6rem,5vw,2.1rem); margin:8px 0 12px; }
      .section-head .eyebrow{ margin-bottom:0; }

      .filters{ display:flex; gap:8px; overflow-x:auto; padding-bottom:6px; margin-bottom:22px; scrollbar-width:none; }
      .filters::-webkit-scrollbar{ display:none; }
      .filter-chip{ flex-shrink:0; padding:9px 18px; border-radius:999px; border:1px solid var(--card-border); color:var(--text-sec); font-size:0.85rem; transition:transform .18s cubic-bezier(.34,1.56,.64,1), background .2s ease, color .2s ease, border-color .2s ease; }
      .filter-chip:active{ transform:scale(.94); }
      .filter-chip.active{ background:var(--cool-green); color:#fff; font-weight:700; border-color:var(--cool-green); }
      .filter-chip:active{ transform:scale(.96); }

      /* ---------- Car grid / card ---------- */
      .car-grid{ display:grid; grid-template-columns:1fr; gap:18px; }
      @media (min-width:640px){ .car-grid{ grid-template-columns:1fr 1fr; } }
      @media (min-width:1024px){ .car-grid{ grid-template-columns:1fr 1fr 1fr; } }

      .car-card{
        text-align:right; background:var(--card); border:1px solid var(--card-border); border-radius:var(--radius);
        overflow:hidden; position:relative; transition:box-shadow .25s ease, border-color .25s ease, transform .15s ease-out;
        transform-style:preserve-3d; will-change:transform;
      }
      .car-card:active{ transform:scale(.98) !important; }
      .tilt-glow{
        position:absolute; inset:0; pointer-events:none; z-index:5; opacity:0; transition:opacity .3s ease;
        background:radial-gradient(circle at var(--glow-x,50%) var(--glow-y,50%), rgba(255,255,255,0.14), transparent 45%);
      }
      @media (min-width:900px){
        .tilt-3d:hover{ border-color:rgba(154,163,172,0.55); box-shadow:0 24px 50px rgba(0,0,0,0.55), 0 0 30px rgba(154,163,172,0.15); }
        .tilt-3d:hover .tilt-glow{ opacity:1; }
        .car-card:hover .car-card-media img{ transform:scale(1.06); }
        .car-card:hover .car-card-arrow{ background:var(--accent-black); color:var(--gold-light); border-color:var(--gold); }
      }
      .car-card-media{ position:relative; aspect-ratio:4/3; overflow:hidden; background:#000; }
      .car-card-media img{ width:100%; height:100%; object-fit:cover; transition:transform .5s ease; }
      .status-pill{
        position:absolute; top:12px; left:12px; display:flex; align-items:center; gap:6px;
        padding:6px 12px; border-radius:999px; font-size:0.72rem; font-weight:700;
        backdrop-filter:blur(6px);
      }
      .status-pill.available{ background:rgba(51,195,111,0.18); color:var(--green); border:1px solid rgba(51,195,111,0.4); }
      .status-pill.booked{ background:rgba(229,84,77,0.18); color:var(--red); border:1px solid rgba(229,84,77,0.4); }
      .status-dot{ width:6px; height:6px; border-radius:50%; background:currentColor; }
      .car-card-body{ padding:16px; display:flex; flex-direction:column; gap:14px; }
      .car-card-top h3{ font-size:1.02rem; font-weight:700; margin-bottom:4px; }
      .car-card-type{ font-size:0.78rem; color:var(--text-sec); }
      .car-card-bottom{ display:flex; align-items:center; justify-content:space-between; }
      .car-price{ display:flex; align-items:baseline; gap:5px; }
      .car-price-num{ font-family:'Poppins',sans-serif; font-weight:700; color:var(--gold-light); font-size:1.15rem; }
      .car-price-num.big{ font-size:1.8rem; }
      .car-price-unit{ font-size:0.75rem; color:var(--text-sec); }
      .car-card-arrow{ width:34px; height:34px; border-radius:50%; border:1px solid var(--card-border); display:flex; align-items:center; justify-content:center; transition:all .2s ease; flex-shrink:0; }

      /* ---------- Fleet showcase (real client photos) ---------- */
      .fleet-showcase{ max-width:1200px; margin:0 auto; padding:16px 20px 8px; position:relative; }
      @media (min-width:900px){ .fleet-showcase{ padding:16px 32px 8px; } }
      .showcase-track{
        display:flex; gap:14px; overflow-x:auto; padding:4px 2px 14px;
        scroll-snap-type:x mandatory; scrollbar-width:none; -webkit-overflow-scrolling:touch;
      }
      .showcase-track::-webkit-scrollbar{ display:none; }
      .showcase-item{
        flex:0 0 auto; width:min(68vw, 280px); aspect-ratio:4/5; border-radius:var(--radius);
        overflow:hidden; border:1px solid var(--card-border); background:var(--card);
        scroll-snap-align:start; transition:transform .35s cubic-bezier(.22,.61,.36,1), box-shadow .35s ease, border-color .35s ease;
      }
      .showcase-item img{ width:100%; height:100%; object-fit:cover; display:block; transition:transform .6s ease; }
      .showcase-item:active{ transform:scale(.97); }
      @media (min-width:900px){
        .showcase-track{ display:grid; grid-template-columns:repeat(5,1fr); overflow:visible; gap:16px; padding:4px 0 6px; }
        .showcase-item{ width:auto; }
        .showcase-item:hover{ transform:translateY(-6px); box-shadow:0 22px 46px rgba(0,0,0,0.5); border-color:rgba(154,163,172,0.5); }
        .showcase-item:hover img{ transform:scale(1.08); }
      }

      /* ---------- Details page ---------- */
      .details-page{ max-width:1000px; margin:0 auto; padding-bottom:110px; }
      @media (min-width:900px){ .details-page{ padding-bottom:60px; } }

      .gallery{ position:relative; }
      .gallery-track-wrap{ position:relative; width:100%; aspect-ratio:4/3; overflow:hidden; background:#000; touch-action:pan-y; }
      @media (min-width:700px){ .gallery-track-wrap{ aspect-ratio:16/9; border-radius:0 0 20px 20px; } }
      .gallery-track{ display:flex; width:100%; height:100%; }
      .gallery-slide{ min-width:100%; height:100%; }
      .gallery-slide img{ width:100%; height:100%; object-fit:cover; }
      .gallery-nav{ position:absolute; top:50%; transform:translateY(-50%); width:38px; height:38px; border-radius:50%; background-color:#161616; background-image:repeating-linear-gradient(45deg, rgba(255,255,255,0.08) 0, rgba(255,255,255,0.08) 1px, transparent 1px, transparent 4px), repeating-linear-gradient(-45deg, rgba(0,0,0,0.6) 0, rgba(0,0,0,0.6) 1px, transparent 1px, transparent 4px); background-size:6px 6px; border:1px solid rgba(255,255,255,0.12); backdrop-filter:blur(6px); display:flex; align-items:center; justify-content:center; color:#fff; transition:transform .18s cubic-bezier(.34,1.56,.64,1), background .18s ease; }
      .gallery-nav:hover{ background:rgba(154,163,172,0.65); }
      .gallery-nav:active{ transform:translateY(-50%) scale(.88); }
      .gallery-nav.prev{ left:12px; }
      .gallery-nav.next{ right:12px; }
      .gallery-dots{ display:flex; justify-content:center; gap:6px; padding:14px 0; }
      .gallery-dot{ width:7px; height:7px; border-radius:50%; background:rgba(255,255,255,0.25); transition:all .2s ease; }
      .gallery-dot.active{ background:var(--blue); width:20px; border-radius:4px; }

      .details-body{ padding:6px 18px 20px; max-width:720px; margin:0 auto; }
      .details-top{ display:flex; align-items:flex-start; justify-content:space-between; gap:12px; padding-top:14px; }
      .details-top h1{ font-size:1.5rem; margin-bottom:6px; }
      .details-type{ font-size:0.85rem; color:var(--text-sec); }
      .details-price{ display:flex; align-items:baseline; gap:8px; margin:18px 0; padding-bottom:18px; border-bottom:1px solid rgba(255,255,255,0.08); }

      .spec-grid{ display:grid; grid-template-columns:1fr 1fr; gap:12px; margin-bottom:26px; }
      @media (min-width:600px){ .spec-grid{ grid-template-columns:repeat(3,1fr); } }
      .spec-item{ display:flex; align-items:center; gap:10px; background:var(--card); border:1px solid var(--card-border); border-radius:12px; padding:12px; }
      .spec-icon{ width:36px; height:36px; border-radius:10px; background-color:#1a1a1a; background-image:repeating-linear-gradient(45deg, rgba(255,255,255,0.06) 0, rgba(255,255,255,0.06) 1px, transparent 1px, transparent 4px), repeating-linear-gradient(-45deg, rgba(0,0,0,0.5) 0, rgba(0,0,0,0.5) 1px, transparent 1px, transparent 4px); background-size:6px 6px; border:1px solid rgba(154,163,172,0.25); color:var(--primary-light); display:flex; align-items:center; justify-content:center; flex-shrink:0; }
      .spec-label{ font-size:0.7rem; color:var(--text-sec); }
      .spec-value{ font-size:0.88rem; font-weight:700; }

      .details-desc h3{ font-size:1.05rem; margin-bottom:10px; }
      .details-desc{ margin-bottom:20px; }
      .details-cta{ margin-top:10px; }

      .sticky-cta{
        position:fixed; bottom:0; left:0; right:0; z-index:60;
        display:flex; align-items:center; justify-content:space-between; gap:14px;
        background-color:rgba(11,11,11,0.92);
        background-image:
          repeating-linear-gradient(45deg, rgba(255,255,255,0.035) 0, rgba(255,255,255,0.035) 1px, transparent 1px, transparent 5px),
          repeating-linear-gradient(-45deg, rgba(0,0,0,0.35) 0, rgba(0,0,0,0.35) 1px, transparent 1px, transparent 5px);
        background-size:7px 7px;
        backdrop-filter:blur(16px); border-top:1px solid rgba(154,163,172,0.2);
        padding:12px 16px calc(12px + env(safe-area-inset-bottom));
      }
      .sticky-cta-price{ display:flex; flex-direction:column; }
      .sticky-cta .btn{ flex-shrink:0; padding:13px 26px; }

      /* ---------- Booking page ---------- */
      .booking-page{ max-width:560px; margin:0 auto; padding:22px 18px 60px; }
      .booking-title{ font-size:1.5rem; margin-bottom:8px; }
      .booking-sub{ margin-bottom:26px; }
      .booking-form{ display:flex; flex-direction:column; gap:16px; }
      .field{ display:flex; flex-direction:column; gap:8px; }
      .field > span{ font-size:0.82rem; color:var(--text-sec); font-weight:500; }
      .field-input{ display:flex; align-items:center; gap:10px; background:var(--card); border:1px solid var(--card-border); border-radius:12px; padding:13px 14px; color:var(--primary-light); transition:border-color .2s ease; }
      .field-input:focus-within{ border-color:var(--primary); }
      .field-input.field-input-error{ border-color:var(--red); }
      .field-error-text{ color:var(--red); font-size:0.78rem; margin-top:2px; }
      .field-input input,.field-input select{ flex:1; background:transparent; border:none; outline:none; color:var(--text); font-size:0.95rem; width:100%; }
      .field-input select{ appearance:none; }
      .field-input input::placeholder{ color:#5f5f5f; }
      .field-row{ display:grid; grid-template-columns:1fr 1fr; gap:12px; }

      .price-summary{ background:var(--card); border:1px solid var(--card-border); border-radius:14px; padding:16px; display:flex; flex-direction:column; gap:10px; }
      .price-summary-row{ display:flex; align-items:center; justify-content:space-between; font-size:0.88rem; color:var(--text-sec); }
      .price-summary-row strong{ color:var(--text); font-family:'Poppins',sans-serif; }
      .price-summary-row.total{ padding-top:10px; border-top:1px solid rgba(255,255,255,0.08); }
      .price-summary-row.total strong{ color:var(--gold-light); font-size:1.15rem; }

      .form-error{ background:rgba(229,84,77,0.1); border:1px solid rgba(229,84,77,0.35); color:#ff8b85; padding:11px 14px; border-radius:10px; font-size:0.85rem; }

      /* ---------- Success ---------- */
      .success-page{ max-width:520px; margin:0 auto; padding:60px 22px 60px; text-align:center; display:flex; flex-direction:column; align-items:center; }
      .success-icon{ color:var(--green); margin-bottom:18px; animation:popIn .5s cubic-bezier(.34,1.56,.64,1); }
      @keyframes popIn{ from{ transform:scale(0); opacity:0; } to{ transform:scale(1); opacity:1; } }
      .success-page h2{ font-size:1.4rem; margin-bottom:8px; }
      .success-sub{ margin-bottom:26px; }
      .success-card{ width:100%; background:var(--card); border:1px solid var(--card-border); border-radius:16px; padding:18px; display:flex; flex-direction:column; gap:12px; margin-bottom:26px; text-align:right; }
      .success-row{ display:flex; align-items:center; justify-content:space-between; font-size:0.88rem; color:var(--text-sec); }
      .success-row strong{ color:var(--text); }
      .success-row.total{ padding-top:12px; border-top:1px solid rgba(255,255,255,0.08); }
      .success-row.total strong{ color:var(--gold-light); font-size:1.2rem; font-family:'Poppins',sans-serif; }

      /* ---------- Footer ---------- */
      .footer{
        max-width:1200px; margin:40px auto 0; padding:40px 18px 120px;
        border-top:1px solid rgba(154,163,172,0.2);
        background-color:transparent;
        background-image:
          repeating-linear-gradient(45deg, rgba(255,255,255,0.02) 0, rgba(255,255,255,0.02) 1px, transparent 1px, transparent 6px),
          repeating-linear-gradient(-45deg, rgba(0,0,0,0.25) 0, rgba(0,0,0,0.25) 1px, transparent 1px, transparent 6px);
        background-size:8px 8px;
        display:flex; flex-direction:column; align-items:center; text-align:center; gap:14px;
      }
      .footer-brand{ margin-bottom:4px; }
      .footer-text{ max-width:420px; }
      .footer-phones{ display:flex; flex-wrap:wrap; gap:14px; justify-content:center; }
      .footer-phone{ display:flex; align-items:center; gap:8px; color:var(--gold-light); font-weight:700; }
      .footer-map-btn{ margin-top:4px; }

      /* ---------- Visit us / map section ---------- */
      .visit-section{ max-width:1200px; margin:60px auto 0; padding:0 18px; }
      .visit-inner{ display:flex; flex-direction:column; gap:28px; background:var(--card); border:1px solid var(--card-border); border-radius:22px; padding:22px; overflow:hidden; }
      @media (min-width:860px){ .visit-inner{ flex-direction:row; align-items:stretch; padding:0; } }
      .visit-media{ border-radius:16px; overflow:hidden; aspect-ratio:16/11; }
      @media (min-width:860px){ .visit-media{ flex:1 1 42%; border-radius:0; aspect-ratio:auto; } }
      .visit-media img{ width:100%; height:100%; object-fit:cover; }
      .visit-info{ flex:1 1 58%; display:flex; flex-direction:column; gap:10px; }
      @media (min-width:860px){ .visit-info{ padding:32px 32px 32px 6px; justify-content:center; } }
      .visit-info h2{ font-size:1.5rem; }
      .visit-address{ color:var(--text-sec); font-size:0.92rem; }
      .hours-list{ margin:12px 0 6px; border-top:1px solid rgba(255,255,255,0.08); padding-top:12px; display:flex; flex-direction:column; gap:6px; }
      .hours-row{ display:flex; justify-content:space-between; font-size:0.86rem; color:var(--text-sec); }
      .hours-row span:first-child{ color:var(--text); font-weight:600; }
      .visit-map-btn{ margin-top:10px; align-self:flex-start; }
      .visit-map-embed{
        position:relative; margin-top:18px; border-radius:18px; overflow:hidden;
        border:1px solid var(--card-border); display:block; height:320px;
      }
      .visit-map-embed-tag{
        position:absolute; bottom:14px; inset-inline-start:14px; z-index:2;
        display:flex; align-items:center; gap:6px;
        background:rgba(11,11,11,0.75); backdrop-filter:blur(6px);
        border:1px solid var(--card-border); border-radius:999px;
        padding:8px 14px; font-size:0.82rem; font-weight:700; color:var(--primary-light);
      }
      .footer-copy{ font-size:0.75rem; color:#5f5f5f; margin-top:10px; }
      @media (min-width:900px){ .footer{ padding-bottom:40px; } }

      /* ---------- Ambient side gallery ---------- */
      .side-ambient{
        position:fixed; top:0; inset-inline-end:0; height:100vh; width:120px;
        z-index:1; pointer-events:none; opacity:0.16; overflow:hidden;
        mask-image:linear-gradient(to left, black, transparent);
        -webkit-mask-image:linear-gradient(to left, black, transparent);
        display:none;
      }
      .side-ambient img{ width:100%; height:100%; object-fit:cover; filter:grayscale(0.2) saturate(1.1); }
      @media (min-width:1100px){
        .side-ambient{ display:block; width:180px; opacity:0.18; }
      }

      /* ---------- WhatsApp + social float stack ---------- */
      .social-float-stack{
        position:fixed; bottom:22px; left:18px; z-index:70;
        display:flex; flex-direction:column; align-items:center; gap:12px;
      }
      .wa-float{
        width:54px; height:54px; border-radius:50%; background:#25D366; color:#fff;
        display:flex; align-items:center; justify-content:center; box-shadow:0 10px 24px rgba(37,211,102,0.4);
        animation:waPulse 2.4s infinite, socialFloatIn .5s cubic-bezier(.34,1.56,.64,1) both;
      }
      .wa-float:active{ transform:scale(.92); }
      .social-float{
        width:46px; height:46px; border-radius:50%; color:#fff;
        display:flex; align-items:center; justify-content:center; box-shadow:0 8px 20px rgba(0,0,0,0.35);
        transition:transform .18s cubic-bezier(.34,1.56,.64,1), opacity .3s ease;
        animation:socialFloatIn .5s cubic-bezier(.34,1.56,.64,1) both;
      }
      .social-float:active{ transform:scale(.9); }
      .instagram-float{ background:radial-gradient(circle at 30% 110%, #fdf497 0%, #fdf497 5%, #fd5949 45%, #d6249f 60%, #285AEB 90%); animation-delay:.08s; }
      .facebook-float{ background:#1877F2; animation-delay:.16s; }
      /* Shown before the admin has saved a link yet — visible, but dimmed
         and inert until the real Facebook/Instagram URL is set. */
      .social-float-pending{ opacity:0.45; cursor:default; }
      .social-float-pending:active{ transform:none; }
      @keyframes socialFloatIn{ from{ opacity:0; transform:translateY(14px) scale(.7); } to{ opacity:1; transform:translateY(0) scale(1); } }
      @keyframes waPulse{ 0%{ box-shadow:0 0 0 0 rgba(37,211,102,0.45), 0 10px 24px rgba(37,211,102,0.35); } 70%{ box-shadow:0 0 0 12px rgba(37,211,102,0), 0 10px 24px rgba(37,211,102,0.35); } 100%{ box-shadow:0 0 0 0 rgba(37,211,102,0), 0 10px 24px rgba(37,211,102,0.35); } }

      .fleet-loading{ display:flex; flex-direction:column; align-items:center; gap:10px; padding:70px 20px; color:var(--text-sec); }
      .spin-icon{ animation:spinIcon 1s linear infinite; color:var(--primary); }
      @keyframes spinIcon{ to{ transform:rotate(360deg); } }

      @media (prefers-reduced-motion: reduce){
        *{ animation-duration:0.001ms !important; animation-iteration-count:1 !important; transition-duration:0.001ms !important; }
      }
    `}</style>
  );
}
